<script lang="ts">import {onMount} from 'svelte';import {claimStore} from '../store';export let id:string;export let name:string;export let onclick:()=>void;let src='',error=false;onMount(()=>{let active=true;claimStore.receipt(id).then(blob=>{if(blob&&active)src=URL.createObjectURL(blob);else if(active)error=true;}).catch(()=>error=true);return()=>{active=false;if(src)URL.revokeObjectURL(src);};});</script>
<button class="receipt-thumb" {onclick} aria-label={'View receipt '+name}>{#if src}<img {src} alt={'Receipt preview: '+name}/>{:else}<span>{error?'Preview unavailable':'Loading receipt…'}</span>{/if}<span>{name}</span></button>